    osc.frequency.setValueAtTime(120, now);
    osc.frequency.exponentialRampToValueAtTime(30, now + 1.5);

    osc.connect(filter);
    filter.connect(gain);
    gain.connect(sfxGain);

    osc.start(now);
    osc.stop(now + 2);

    // Noise burst for debris
    const bufferSize = audioContext.sampleRate * 0.5;
    const buffer = audioContext.createBuffer(1, bufferSize, audioContext.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < bufferSize; i++) {
      data[i] = (Math.random() * 2 - 1) * Math.exp(-i / (bufferSize * 0.3));
    }

    const noise = audioContext.createBufferSource();
    const noiseGain = audioContext.createGain();
    const noiseFilter = audioContext.createBiquadFilter();

    noise.buffer = buffer;
    noiseFilter.type = 'bandpass';
    noiseFilter.frequency.value = 800;
    noiseFilter.Q.value = 2;

    noiseGain.gain.setValueAtTime(0.2, now);
    noiseGain.gain.exponentialRampToValueAtTime(0.001, now + 0.5);

    noise.connect(noiseFilter);
    noiseFilter.connect(noiseGain);
    noiseGain.connect(sfxGain);

    noise.start(now);
  }

  function setMasterVolume(v) {
    if (masterGain) masterGain.gain.value = Math.max(0, Math.min(1, v));
  }

  function setSfxVolume(v) {
    if (sfxGain) sfxGain.gain.value = Math.max(0, Math.min(1, v));
  }

  function setMusicVolume(v) {
    if (musicGain) musicGain.gain.value = Math.max(0, Math.min(1, v));
  }

  return {
    init,
    playEngine,
    updateEngineSound,
    stopEngine,
    playSiren,
    updateSirenSound,
    stopSiren,
    playGunshot,
    playPunch,
    playHit,
    playPedScream,
    playPedDeath,
    playEnterCar,
    playExitCar,
    playWasted,
    playBusted,
    playRespawn,
    playPickup,
    playMissionStart,
    playMissionComplete,
    playHeli,
    stopHeli,
    playExplosion,
    setMasterVolume,
    setSfxVolume,
    setMusicVolume,
    get context() { return audioContext; }
  };
}
